class Solution {
    public String getHint(String secret,String guess){
        int bulls=0;
        int[] first=new int[10],second=new int[10];
        for(int i=0;i<secret.length();i++){
            if(secret.charAt(i)==guess.charAt(i))bulls++;
            else{
                first[secret.charAt(i)-'0']++;
                second[guess.charAt(i)-'0']++;
            }
        }
        int cows=0;
        for(int d=0;d<10;d++)cows+=Math.min(first[d],second[d]);
        return bulls+"A"+cows+"B";
    }
}

code.kotlin:
class Solution {
    fun getHint(secret:String,guess:String):String{
        var bulls=0;
        val first=IntArray(10);
        val second=IntArray(10);
        for(i in secret.indices){
            if(secret[i]==guess[i])bulls++ else{
                first[secret[i]-'0']++;
                second[guess[i]-'0']++
            }
        };
        var cows=0;
        for(d in 0..9)cows+=minOf(first[d],second[d]);
        return bulls.toString()+"A"+cows+"B"
    }
}

